def write(repo):
    for slug, (heading, detail, source, guide) in CONTEXT.items():
        page = Path(repo) / 'directory' / slug / 'index.html'
        markup = page.read_text()
        markup = re.sub(r'<!-- INDUSTRY_CONTEXT_START -->.*?<!-- INDUSTRY_CONTEXT_END -->', '', markup, flags=re.S)
        block = f'''<!-- INDUSTRY_CONTEXT_START --><section class="profile-copy"><h2>{heading}</h2><p>{detail}</p><p><a href="{source}" rel="noopener noreferrer">Official service information</a> · Checked {'October 13, 2026' if slug in ('pittsburgh-music-academy', 'action-appliance-service', 'ace-lock', 'expert-window-cleaning', 'world-of-rugs', 'global-wordsmiths', 'mathnasium-squirrel-hill', 'pittsburgh-ballet-theatre', 'apex-junk-removal-hauling', 'concept-art-gallery', 'animal-friends-university', 'circa-barbershop-pittsburgh', 'gaynors-school-of-cooking', 'primo-tailoring-pittsburgh', 'debatin-piano-service', 'thornton-company-north-hills', 'the-final-touch-verona', 'henne-jewelers-shadyside', 'the-studio-by-pgh-candle', 'installation-services-modern-day-garage', 'asahi-ramen-brookline', 'pittsburgh-pottery-carnegie', 'la-dolce-vita-south-side', 'pittsburgh-glass-center', 'okane-downtown-pittsburgh', 'penn-fencing-inc', 'ruby-flora-bethel-park', 'cork-crust', 'the-shelf-love-society', 'foxhole-tavern-aspinwall', 'sea-monkey-strip-district', 'game-masters-perry-highway', 'diamondmill-auto-spa', 'hong-hot-pot-mcknight', 'laser-storm-pittsburgh', 'markantone-painting', 'dooboo-east-liberty', 'phat-bagel-bloomfield', 'mad-anthonys-bier-stube-ambridge', 'haveli-monroeville', 'millie-s-homemade-ice-cream', 'lao-sze-chuan-sheraton-drive', 'tapville-social-pittsburgh', 'ruckus-cafe-downtown', 'fnf-pizzeria-mt-lebanon', 'northwood-tree-care', 'advanced-basement-solutions', 'pho-van-strip-district') else 'October 12, 2026' if slug in ('squirrel-hill-shoe-repair', 'model-cleaners-upper-st-clair') else 'October 10, 2026'}.</p><p>Featured in our <a href="/news/{guide}/">Pittsburgh industry comparison guide</a>. Inclusion is an editorial selection, not an independent award or a guarantee of service quality.</p></section><!-- INDUSTRY_CONTEXT_END -->'''
        assert '</main>' in markup
        page.write_text(markup.replace('</main>', block + '</main>', 1))
    return len(CONTEXT)
